`,_=()=>{r.useId();const[u,k]=r.useState("twitter_2020_vishing_scam"),[s,v]=r.useState(3.5),[o,S]=r.useState(3.5),[c,w]=r.useState(3.5),[l,I]=r.useState(3),[x,C]=r.useState("kolkata_multitier_bec_defense"),[f,E]=r.useState("fido2_webauthn_registration_js"),y={twitter_2020_vishing_scam:{key:"twitter_2020_vishing_scam",name:"1. 2020 Twitter / X Bitcoin Scam (Spear Vishing & Admin Hijack)",category:"REMOTE IT HELPDESK VISHING",categoryBadge:"bg-rose-950 text-rose-300 border-rose-800",targetEntity:"Twitter Customer Support & Admin Gateway",attackVector:"Attackers called remote employees posing as internal IT staff, directing them to a fake VPN portal to harvest credentials and bypass 2FA, gaining access to the internal administrative tool.",financialImpact:"130 high-profile accounts hijacked (Barack Obama, Elon Musk, Apple); ₹1 Crore+ in Bitcoin stolen in 2 hours; severe brand damage.",rootVulnerability:"Reliance on phishable SMS/App 2FA and excessive standing privileges inside internal support tools.",resilientDefense:"Mandatory FIDO2 hardware keys (YubiKey), Out-of-Band verification for admin account resets, and least-privilege RBAC.",codeSnippet:`// 2020 Twitter Incident Attack Chain:
// 1. Vector      : Spear Vishing phone calls to remote employees posing as internal IT Helpdesk
